 // Array<nsMsgViewIndex> getIndicesForSelection();
 NS_IMETHODIMP
 nsMsgDBView::GetIndicesForSelection(nsTArray<nsMsgViewIndex>& indices) {
@@ -6233,13 +6227,6 @@ nsMsgDBView::OnDeleteCompleted(bool aSucceeded) {
